/// Core transaction records for all financial activities including customer
/// payments, seller payouts, and platform fees. Contains comprehensive
/// payment processing details with status tracking, fraud detection, and
/// audit compliance. Each transaction represents a complete financial event
/// with detailed logging for dispute resolution and financial
/// reconciliation.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_transactions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order this transaction is associated with. {@link
  /// ecommerce_mall_orders.id}
  ecommerce_mall_order_id String @db.Uuid

  /// Customer who made the payment. {@link ecommerce_mall_customers.id}
  ecommerce_mall_customer_id String @db.Uuid

  /// Seller receiving payment (for customer-to-seller transactions). {@link
  /// ecommerce_mall_sellers.id}
  ecommerce_mall_seller_id String @db.Uuid

  /// Payment method used for this transaction (if applicable). {@link
  /// ecommerce_mall_payment_methods.id}
  ecommerce_mall_payment_method_id String? @db.Uuid

  /// Type of transaction: payment, refund, chargeback, payout, fee,
  /// commission, etc.
  transaction_type String

  /// Transaction amount in base currency (positive for credits, negative for
  /// debits).
  amount Float @db.DoublePrecision

  /// ISO currency code for transaction amount (USD, EUR, GBP, etc.).
  currency String

  /// Exchange rate used if transaction involves currency conversion.
  exchange_rate Float? @db.DoublePrecision

  /// Transaction amount in user's currency (if different from base currency).
  amount_in_currency Float? @db.DoublePrecision

  /// Transaction status: pending, processing, completed, failed, cancelled,
  /// disputed, refunded.
  status String

  /// Business workflow status: authorized, captured, settled, voided,
  /// chargeback_pending, etc.
  business_status String

  /// Payment processor or gateway used: stripe, paypal, square, authorize_net,
  /// etc.
  payment_gateway String

  /// Transaction ID from payment gateway (external reference).
  gateway_transaction_id String?

  /// Response code from payment gateway indicating success/failure reason.
  gateway_response_code String?

  /// Response message from payment gateway with detailed status.
  gateway_response_message String?

  /// Authorization code from payment processor for approved transactions.
  authorization_code String?

  /// Batch ID for settlement processing in payment gateway.
  settlement_batch_id String?

  /// Detailed reason for transaction failure or cancellation.
  failure_reason String?

  /// Fraud detection score (0.0 to 1.0) from payment processor or internal
  /// systems.
  fraud_score Float? @db.DoublePrecision

  /// JSON array of fraud indicators detected during transaction processing.
  fraud_indicators String?

  /// Risk level assessment: low, medium, high, critical.
  risk_level String

  /// IP address used for transaction (for fraud analysis and audit).
  ip_address String?

  /// User agent string from device used for transaction.
  user_agent String?

  /// Whether billing address was verified against payment processor records.
  billing_address_verified Boolean

  /// Whether CVV verification passed during transaction.
  cvv_verified Boolean

  /// 3D Secure authentication status: not_required, successful, failed,
  /// challenged.
  three_d_secure_status String?

  /// JSON metadata for additional transaction information (gateway-specific
  /// data, custom fields, etc.).
  metadata String? @db.VarChar(80000)

  /// Internal notes about transaction for customer service and dispute
  /// resolution.
  notes String?

  /// Timestamp when transaction was processed/settled by payment gateway.
  processed_at DateTime? @db.Timestamptz

  /// Timestamp when transaction funds were settled to merchant account.
  settled_at DateTime? @db.Timestamptz

  /// Timestamp when transaction record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when transaction record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order ecommerce_mall_orders @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)
  customer ecommerce_mall_customers @relation(fields: [ecommerce_mall_customer_id], references: [id], onDelete: Cascade)
  seller ecommerce_mall_sellers @relation(fields: [ecommerce_mall_seller_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  paymentMethod ecommerce_mall_payment_methods? @relation(fields: [ecommerce_mall_payment_method_id], references: [id], onDelete: Cascade, map: "ecommerce_mall_transactions_ecommerce_mall_payment_met_3e53f0ba")

  ecommerce_mall_refunds ecommerce_mall_refunds[]
  ecommerce_mall_disputes ecommerce_mall_disputes[]
  ecommerce_mall_payment_audits ecommerce_mall_payment_audits[]

  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_payment_method_id], map: "ecommerce_mall_transactions_ecommerce_mall_payment_met_8bb9a9e8")

  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_order_id, transaction_type, gateway_transaction_id], map: "ecommerce_mall_transactions_ecommerce_mall_order_id_tr_3670e253")
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_customer_id, status], map: "ecommerce_mall_transactions_ecommerce_mall_customer_id_38d92c3b")
  @@index([ecommerce_mall_seller_id, status])
  @@index([payment_gateway, status])
  @@index([transaction_type, status])
  @@index([created_at])
  @@index([gateway_response_message(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([failure_reason(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([notes(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Refund transaction records linked to original orders and payments. Tracks
/// refund processing with status workflows, approval chains, and settlement
/// tracking. Supports both automatic and manual refund processing with
/// detailed audit trails for compliance and customer service. Each refund
/// maintains reference to original transaction and provides complete
/// financial reconciliation.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_refunds {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Original transaction being refunded. {@link
  /// ecommerce_mall_transactions.id}
  ecommerce_mall_transaction_id String @db.Uuid

  /// Order associated with this refund. {@link ecommerce_mall_orders.id}
  ecommerce_mall_order_id String @db.Uuid

  /// Customer receiving the refund. {@link ecommerce_mall_customers.id}
  ecommerce_mall_customer_id String @db.Uuid

  /// Seller responsible for processing the refund. {@link
  /// ecommerce_mall_sellers.id}
  ecommerce_mall_seller_id String @db.Uuid

  /// Administrator who processed this refund (for manual refunds). {@link
  /// ecommerce_mall_administrators.id}
  ecommerce_mall_administrator_id String? @db.Uuid

  /// Type of refund: full, partial, exchange, store_credit, warranty,
  /// chargeback_response.
  refund_type String

  /// Refund amount in base currency.
  amount Float @db.DoublePrecision

  /// ISO currency code for refund amount.
  currency String

  /// Refund amount in customer's currency (if different from base currency).
  amount_in_currency Float? @db.DoublePrecision

  /// Predefined reason code: changed_mind, damaged_product, wrong_item,
  /// late_delivery, not_as_described, other.
  reason_code String

  /// Detailed description of refund reason provided by customer or seller.
  reason_details String?

  /// Refund status: pending_review, approved, rejected, processing, completed,
  /// failed, cancelled.
  status String

  /// Business workflow status: initiated, under_review, approved, in_progress,
  /// settled, rejected.
  business_status String

  /// Method of refund: original_payment, store_credit, bank_transfer, check,
  /// digital_wallet.
  refund_method String

  /// Whether this refund was processed automatically by system or manually by
  /// administrator/seller.
  is_automatic Boolean

  /// Whether this is a partial refund or full refund of the original
  /// transaction.
  is_partial Boolean

  /// Restocking fee deducted from refund amount (if applicable).
  restocking_fee Float @db.DoublePrecision

  /// Return shipping cost deducted from refund amount (if customer
  /// responsible).
  return_shipping_cost Float @db.DoublePrecision

  /// Administrative fee deducted from refund amount (if applicable).
  admin_fee Float @db.DoublePrecision

  /// Payment gateway handling the refund processing.
  payment_gateway String?

  /// Refund transaction ID from payment gateway (external reference).
  gateway_refund_id String?

  /// Batch ID for refund settlement in payment gateway.
  settlement_batch_id String?

  /// Tracking number for return shipment (if physical return required).
  return_tracking_number String?

  /// Shipping carrier used for return shipment.
  return_carrier String?

  /// Timestamp when return shipment was delivered to seller.
  return_delivered_at DateTime? @db.Timestamptz

  /// Notes about condition of returned items from seller inspection.
  return_condition_notes String?

  /// Date when returned items were inspected by seller.
  inspection_date DateTime? @db.Timestamptz

  /// Date when refund was approved for processing.
  approval_date DateTime? @db.Timestamptz

  /// Date when refund was submitted to payment gateway for processing.
  processing_date DateTime? @db.Timestamptz

  /// Date when refund was completed and funds were returned to customer.
  completed_date DateTime? @db.Timestamptz

  /// Reason for refund processing failure or rejection.
  failure_reason String?

  /// Whether customer has been notified about refund status changes.
  customer_notification_sent Boolean

  /// JSON metadata for additional refund information (images, documents,
  /// custom fields).
  metadata String? @db.VarChar(80000)

  /// Timestamp when refund request was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when refund record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  originalTransaction ecommerce_mall_transactions @relation(fields: [ecommerce_mall_transaction_id], references: [id], onDelete: Cascade)
  order ecommerce_mall_orders @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)
  customer ecommerce_mall_customers @relation(fields: [ecommerce_mall_customer_id], references: [id], onDelete: Cascade)
  seller ecommerce_mall_sellers @relation(fields: [ecommerce_mall_seller_id], references: [id], onDelete: Cascade)
  processedBy ecommerce_mall_administrators? @relation(fields: [ecommerce_mall_administrator_id], references: [id], onDelete: Cascade)

  @@index([ecommerce_mall_order_id])
  @@index([ecommerce_mall_administrator_id])

  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_transaction_id, refund_type], map: "ecommerce_mall_refunds_ecommerce_mall_transaction_id_r_e549ed04")
  @@index([ecommerce_mall_customer_id, status])
  @@index([ecommerce_mall_seller_id, status])
  @@index([status, business_status])
  @@index([refund_type, is_automatic])
  @@index([created_at])
  @@index([reason_details(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([return_condition_notes(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([failure_reason(ops: raw("gin_trgm_ops"))], type: Gin)
