/// Order shipment records tracking package dispatch and delivery through
/// shipping carriers.
///
/// Stores detailed information about each shipment including order
/// association, shipping method, carrier details, and current delivery
/// status. Each shipment represents a physical package sent to fulfill
/// customer orders.
///
/// Shipments include tracking information, estimated delivery dates, actual
/// delivery confirmations, and shipping cost details. The system maintains
/// comprehensive audit trails of all shipment status changes.
///
/// Customers receive automated notifications at each shipment milestone from
/// dispatch through final delivery confirmation. Sellers use shipment
/// records to manage their fulfillment operations and customer
/// communications.
///
/// @namespace Fulfillment
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_shipments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated order for this shipment. {@link ecommerce_mall_orders.id}
  ecommerce_mall_order_id String @db.Uuid

  /// Shipping method used for this shipment. {@link
  /// ecommerce_mall_shipping_methods.id}
  ecommerce_mall_shipping_method_id String @db.Uuid

  /// Current shipment status (pending, processing, shipped, in_transit,
  /// out_for_delivery, delivered, exception).
  status String

  /// Shipping carrier name (UPS, FedEx, USPS, DHL, etc.).
  carrier_name String

  /// Estimated delivery date based on shipping method and destination.
  estimated_delivery_date DateTime @db.Timestamptz

  /// Actual delivery confirmation date and time.
  actual_delivery_date DateTime? @db.Timestamptz

  /// Total shipping cost charged for this shipment.
  shipping_cost Float @db.DoublePrecision

  /// Package weight in kilograms for shipping calculations.
  weight_kg Float @db.DoublePrecision

  /// Package dimensions in centimeters (LxWxH format).
  dimensions_cm String?

  /// Special handling instructions for the carrier.
  special_instructions String?

  /// Shipment creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last shipment status update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for audit purposes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  order          ecommerce_mall_orders           @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)
  shippingMethod ecommerce_mall_shipping_methods @relation(fields: [ecommerce_mall_shipping_method_id], references: [id], onDelete: Cascade)

  ecommerce_mall_tracking_numbers       ecommerce_mall_tracking_numbers[]
  ecommerce_mall_delivery_confirmations ecommerce_mall_delivery_confirmations[]

  @@index([ecommerce_mall_shipping_method_id])
  @@index([ecommerce_mall_order_id, status])
  @@index([carrier_name, status])
  @@index([estimated_delivery_date])
}

/// Available shipping methods and carriers with pricing and delivery time
/// information.
///
/// Defines all shipping options available to customers including carrier
/// services, delivery timeframes, pricing structures, and geographic
/// coverage areas. Each shipping method represents a specific service level
/// offered by shipping carriers.
///
/// Shipping methods include detailed information about delivery speeds, cost
/// calculations, tracking capabilities, and any special handling
/// requirements. The system automatically calculates shipping costs based on
/// order details and selected shipping methods.
///
/// Customers select shipping methods during checkout based on their delivery
/// preferences and urgency. Sellers configure which shipping methods are
/// available for their products and locations.
///
/// @namespace Fulfillment
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_shipping_methods {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Shipping method name (Standard Ground, Express Overnight, Priority Mail,
  /// etc.).
  name String

  /// Shipping carrier providing this service.
  carrier_name String

  /// Service level indicator (ground, express, overnight, international).
  service_level String

  /// Estimated delivery time in business days.
  estimated_delivery_days Int @db.Integer

  /// Base shipping cost for this method.
  base_cost Float @db.DoublePrecision

  /// Additional cost per kilogram of package weight.
  cost_per_kg Float @db.DoublePrecision

  /// Whether this method provides tracking information.
  tracking_available Boolean

  /// Whether signature confirmation is required for delivery.
  signature_required Boolean

  /// Whether shipping insurance is available for this method.
  insurance_available Boolean

  /// Whether this method supports international shipping.
  international_eligible Boolean

  /// Whether this shipping method is currently available for orders.
  active Boolean

  /// Shipping method creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for shipping method details.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for audit purposes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  ecommerce_mall_orders    ecommerce_mall_orders[]
  ecommerce_mall_shipments ecommerce_mall_shipments[]

  @@unique([name, carrier_name])
  @@index([carrier_name, active])
  // spellchecker: ignore-next-line
  @@index([service_level, estimated_delivery_days], map: "ecommerce_mall_shipping_methods_service_level_estimate_7dac5372")
}

/// Tracking numbers associated with shipments for real-time delivery status
/// updates.
///
/// Stores individual tracking numbers for each shipment, enabling customers
/// and sellers to monitor package movement through carrier tracking systems.
/// Each tracking number links to a specific shipment and provides real-time
/// status updates.
///
/// Tracking numbers include carrier tracking details, current status
/// information, last update timestamps, and any delivery exceptions or
/// delays. The system automatically updates tracking information through
/// carrier APIs.
///
/// This entity supports multiple tracking numbers per shipment for complex
/// fulfillment scenarios and provides comprehensive delivery visibility for
/// customer service and order management.
///
/// @namespace Fulfillment
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_tracking_numbers {
  //----
  // COLUMNS
  //----
