  ecommerce_mall_shipment_id String @db.Uuid

  /// Associated tracking number for this delivery. {@link
  /// ecommerce_mall_tracking_numbers.id}
  ecommerce_mall_tracking_number_id String? @db.Uuid

  /// Exact timestamp when delivery was confirmed.
  delivery_timestamp DateTime @db.Timestamptz

  /// Name of person who received the package.
  recipient_name String

  /// URL to delivery signature image if available.
  signature_url String? @db.VarChar(80000)

  /// Method of delivery confirmation (signature, photo, verbal, etc.).
  delivery_method String

  /// Additional notes about the delivery process.
  delivery_notes String?

  /// URL to delivery photo if available.
  photo_url String? @db.VarChar(80000)

  /// Delivery confirmation record creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  shipment       ecommerce_mall_shipments         @relation(fields: [ecommerce_mall_shipment_id], references: [id], onDelete: Cascade, map: "ecommerce_mall_delivery_confirmations_ecommerce_mall_s_86de0811")
  // spellchecker: ignore-next-line
  trackingNumber ecommerce_mall_tracking_numbers? @relation(fields: [ecommerce_mall_tracking_number_id], references: [id], onDelete: Cascade, map: "ecommerce_mall_delivery_confirmations_ecommerce_mall_t_17182003")

  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_tracking_number_id], map: "ecommerce_mall_delivery_confirmations_ecommerce_mall_t_35bcfc88")
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_shipment_id], map: "ecommerce_mall_delivery_confirmations_ecommerce_mall_s_31da73c7")
  @@index([delivery_timestamp])
}

/// Return authorization requests allowing customers to return products with
