  ecommerce_mall_customer_id String @db.Uuid

  /// Type of actor who created the return authorization (customer, seller).
  actor_type String

  /// Return authorization status (pending, approved, rejected, expired).
  status String

  /// Reason for return request (damaged, wrong_item, not_satisfied, etc.).
  return_reason String

